#pragma once
#include "soft_assertions.h"
namespace suitecut::runner {
inline const char* SoftRawName(SoftRawOutcome raw){switch(raw){case SoftRawOutcome::Passed:return "passed";case SoftRawOutcome::RecognizedMismatch:return "recognizedMismatch";case SoftRawOutcome::RecognizedDeadline:return "recognizedDeadline";case SoftRawOutcome::OtherFailure:return "otherFailure";}throw std::invalid_argument("Invalid native soft raw outcome");}
inline const char* SoftReceiptName(SoftReceipt receipt){switch(receipt){case SoftReceipt::Mismatch:return "mismatch";case SoftReceipt::AcceptedDeadline:return "acceptedDeadline";case SoftReceipt::OtherFailure:return "otherFailure";case SoftReceipt::Late:return "late";case SoftReceipt::Canceled:return "canceled";case SoftReceipt::WorkerExited:return "workerExited";}throw std::invalid_argument("Invalid native soft receipt");}
template<class Report>size_t ValidateSoftAssertions(const Report& report){
  if(report.soft_assertions.size()>SoftAssertions::kRecords)throw std::invalid_argument("Native soft report record capacity exceeded");
  std::map<uint64_t,const SoftAssertionRecord*> records;std::set<std::pair<unsigned,uint64_t>> requests;std::map<uint64_t,size_t> failures;size_t charge=0;
  for(const auto& r:report.soft_assertions){const auto& o=r.owner;(void)SoftRawName(r.raw);(void)SoftReceiptName(r.receipt);
    if(!r.id||!r.request||!records.emplace(r.id,&r).second||!requests.emplace(o.worker_index,r.request).second||!o.test_id||!o.attempt_generation||!o.scope||!o.scope_generation||!o.worker_index||o.pid<=0||o.pid>INT32_MAX||(o.callback_kind!="body"&&o.callback_kind!="beforeEach"&&o.callback_kind!="afterEach")||(o.callback_kind!="body"&&!o.callback_token)||r.cleanup!=(o.callback_kind=="afterEach")||!std::isfinite(r.admitted)||!std::isfinite(r.received)||r.admitted<0||r.received<r.admitted||!JsonString(r.error_json,8192)||!JsonString(r.cancel_reason_json,8192)||(r.location&&(!ValidStepLocation(*r.location)||r.location->explicit_location)))throw std::invalid_argument("Native soft report has invalid actual owner/error/timestamp metadata");
    if(std::none_of(report.attempts.begin(),report.attempts.end(),[&](const auto& a){return a.test_id==o.test_id&&a.generation==o.attempt_generation&&a.worker_index==o.worker_index&&a.pid==o.pid;})||std::none_of(report.workers.begin(),report.workers.end(),[&](const auto& w){return w.worker_index==o.worker_index&&w.pid==o.pid&&w.exit_code>=0;}))throw std::invalid_argument("Native soft report has no actual attempt/OS worker receipt");
    if(IsAcceptedSoftFailure(r.receipt)&&((r.receipt==SoftReceipt::Mismatch?r.raw!=SoftRawOutcome::RecognizedMismatch:r.raw!=SoftRawOutcome::RecognizedDeadline)||r.cancel_reason_json!="\"\""||++failures[o.attempt_generation]>SoftAssertions::kPerAttempt))throw std::invalid_argument("Native accepted soft failure has contradictory raw/cancel evidence");
    if(r.receipt==SoftReceipt::OtherFailure&&r.raw!=SoftRawOutcome::OtherFailure)throw std::invalid_argument("Native soft hard diagnostic has no raw failure");
    if(r.step){const auto s=std::find_if(report.steps.begin(),report.steps.end(),[&](const auto& step){return step.id==r.step;});if(s==report.steps.end()||s->owner!=o||s->started>r.admitted||!s->received||*s->received<r.received)throw std::invalid_argument("Native soft report has no actual step/raw retirement owner");}
    const auto bytes=r.error_json.size()+r.cancel_reason_json.size()+o.callback_kind.size()+(r.location?r.location->file_json.size():0)+1024;if(bytes>SoftAssertions::kMetadata-charge)throw std::invalid_argument("Native soft report metadata capacity exceeded");charge+=bytes;
  }
  for(const auto& step:report.steps)if(step.soft_error_id){const auto r=records.find(step.soft_error_id);if(r==records.end()||!IsAcceptedSoftFailure(r->second->receipt)||r->second->owner!=step.owner||!r->second->step||step.soft_error_json!=r->second->error_json)throw std::invalid_argument("Native step soft cause has no exact accepted soft failure");uint64_t id=r->second->step;bool found=false;for(size_t depth=0;id&&depth<=TestSteps::kDepth;++depth){if(id==step.id){found=true;break;}const auto s=std::find_if(report.steps.begin(),report.steps.end(),[&](const auto& value){return value.id==id;});if(s==report.steps.end()||s->owner!=step.owner)break;id=s->parent;}if(!found)throw std::invalid_argument("Native step soft cause is not an actual descendant");}else if(step.soft_error_json!="\"\"")throw std::invalid_argument("Native step soft error lost its native cause ID");
  for(const auto& a:report.attempts)if(a.soft_error_id){const auto r=records.find(a.soft_error_id);if(r==records.end()||!IsAcceptedSoftFailure(r->second->receipt)||r->second->owner.test_id!=a.test_id||r->second->owner.attempt_generation!=a.generation||r->second->owner.worker_index!=a.worker_index||r->second->owner.pid!=a.pid||a.originating_step||a.status!="failed"||a.error_json!=r->second->error_json)throw std::invalid_argument("Native attempt primary soft cause has no actual admitted soft failure");}
  return charge;
}
template<class Writer>void PutSoftAssertions(Writer& file,const std::vector<SoftAssertionRecord>& records){
  file.Put("[");bool first=true;for(const auto& r:records){if(!first)file.Put(",");first=false;const auto& o=r.owner;
    file.Put("{\"id\":\"");file.NumberValue(r.id);file.Put("\",\"requestId\":\"");file.NumberValue(r.request);file.Put("\",\"testId\":\"");file.NumberValue(o.test_id);file.Put("\",\"generation\":\"");file.NumberValue(o.attempt_generation);file.Put("\",\"callbackToken\":\"");file.NumberValue(o.callback_token);file.Put("\",\"scopeId\":\"");file.NumberValue(o.scope);file.Put("\",\"scopeGeneration\":\"");file.NumberValue(o.scope_generation);file.Put("\",\"workerIndex\":");file.NumberValue(o.worker_index);file.Put(",\"pid\":");file.NumberValue(o.pid);file.Put(",\"callbackKind\":\"");file.Put(o.callback_kind);file.Put("\",\"admittedMonotonicMs\":");file.NumberValue(r.admitted);file.Put(",\"receiptMonotonicMs\":");file.NumberValue(r.received);file.Put(",\"rawOutcome\":\"");file.Put(SoftRawName(r.raw));file.Put("\",\"receipt\":\"");file.Put(SoftReceiptName(r.receipt));file.Put("\",\"acceptedMismatch\":");file.Put(r.receipt==SoftReceipt::Mismatch?"true":"false");file.Put(",\"acceptedDeadline\":");file.Put(r.receipt==SoftReceipt::AcceptedDeadline?"true":"false");file.Put(",\"cleanup\":");file.Put(r.cleanup?"true":"false");file.Put(",\"error\":");file.Put(r.error_json);
    if(r.step){file.Put(",\"stepId\":\"");file.NumberValue(r.step);file.Put("\"");}if(r.cancel_reason_json!="\"\""){file.Put(",\"cancelReason\":");file.Put(r.cancel_reason_json);}if(r.location){file.Put(",\"location\":{\"file\":");file.Put(r.location->file_json);file.Put(",\"line\":");file.NumberValue(r.location->line);file.Put(",\"column\":");file.NumberValue(r.location->column);file.Put(",\"origin\":\"callsite\"}");}file.Put("}");
  }file.Put("]");
}
}
